{
  "packet_id": "H6-T03-1",
  "claim_id": "C018",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C018.component",
    "value": "The proposed observational test examines whether predicted approval records are locatable, linked to the relevant order, demonstrably prior to placement and associated with authority fitting the applicable rule.",
    "scope": "Proposed observation criteria, not findings that any order satisfies them. The precise reach of the later demonstrative qualifier is implicit, but the instruction itself is prospective.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P015 supplies all four observational criteria and is itself prospective; P018 reinforces that the signal observations are proposed tests."
    }
  },
  "signal_basis": {
    "component_id": "C018.signal_basis",
    "value": "Record order identifiers, approval content, authority and distinct event and record dates; compare observed links and timing with route predictions, checking record availability, order linkage, precedence and applicable authority.",
    "scope": "A proposed documentary observation procedure, without asserting positive findings for any order.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify the recorded evidence, comparison procedure, observational criteria and prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C018.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported directly as a description of the proposed test; no unresolved empirical relation is needed."
    }
  },
  "rationale": "The operation and signal explicitly implement the criteria described by C018. Its limited claim concerns what the test examines, so it requires no inference that approvals occurred or that any order complied.",
  "uncertainty": "P018's precise backward reference is implicit, but P015 independently establishes the prospective character of the criteria. This does not affect the warrant.",
  "anomalies": []
}
